import { Connection, PublicKey } from "@solana/web3.js";
import { RpcRouter } from "../lib/rpc-router";

export interface DuplicateEventsHashReport {
  totalSignaturesScanned: number;
  totalConfirmedBatches: number;
  uniqueEventsHashes: number;
  duplicateHashes: Array<{
    eventsHash: string;
    count: number;
    signatures: string[];
    batchIds: string[];
  }>;
  ok: boolean;
}

/**
 * Historical static fixture hashes recorded in KNOWN_LIMITS.md.
 * Generated by early development and test fixtures prior to dynamic run IDs.
 */
export const KNOWN_LEGACY_FIXTURE_HASHES = new Set([
  "TESTHASH01",
  "3cce3bad06dd5e9964395dde619a8802066f3220d9e6d884368f889db355b6e8",
  "4cb435ff789959db025e1dfe3e42d6101ef19f8c2c6ea2a1511158f838d07de6",
]);

/**
 * Queries getSignaturesForAddress for the treasury on Solana DevNet, paginating
 * across the FULL history with the `before` cursor until no more results.
 * Parses confirmed memo instructions matching `trickle:v1:<batchId>:<eventsHash>`,
 * and asserts that no events hash appears in more than one confirmed batch.
 *
 * Blueprint Section 5.5 & Phase 4 Gate Requirement:
 * Fails (throws Error) if any events hash appears in more than one confirmed batch.
 */
export async function assertNoDuplicateEventsHashes(
  connectionOrRouter: Connection | RpcRouter,
  treasuryAddress: PublicKey | string,
  options?: {
    pageSize?: number;
    limit?: number;
    ignoreLegacyHashes?: boolean;
    failOnError?: boolean;
  }
): Promise<DuplicateEventsHashReport> {
  const pubkey = typeof treasuryAddress === "string" ? new PublicKey(treasuryAddress) : treasuryAddress;
  const pageSize = options?.pageSize ?? options?.limit ?? 100;
  const ignoreLegacy = options?.ignoreLegacyHashes ?? false;
  const failOnError = options?.failOnError ?? true;

  // 1. Paginate across FULL history using before cursor until no more results
  const allSignatures: any[] = [];
  let before: string | undefined = undefined;

  while (true) {
    let page: any[] = [];
    if ("callWithFailover" in connectionOrRouter) {
      const res = await connectionOrRouter.callWithFailover(async (conn) => {
        return await conn.getSignaturesForAddress(pubkey, { limit: pageSize, before });
      });
      page = res ?? [];
    } else {
      page = (await connectionOrRouter.getSignaturesForAddress(pubkey, { limit: pageSize, before })) ?? [];
    }

    if (!page || page.length === 0) {
      break;
    }

    allSignatures.push(...page);
    before = page[page.length - 1].signature;

    if (page.length < pageSize) {
      break;
    }
  }

  // 2. Parse confirmed settlement batch memos (prefix: trickle:v1:)
  const hashToBatches = new Map<string, Array<{ signature: string; batchId: string }>>();
  let totalConfirmedBatches = 0;

  for (const sigInfo of allSignatures) {
    if (!sigInfo.memo) continue;
    // Extract memo string from SPL memo output
    const match =
      sigInfo.memo.match(/trickle:v1:([^:]+):([a-f0-9]{64})/i) ||
      sigInfo.memo.match(/trickle:v1:([^:]+):([^:\s\]]+)/i);
    if (!match) continue;

    const batchId = match[1];
    const eventsHash = match[2];

    if (ignoreLegacy && KNOWN_LEGACY_FIXTURE_HASHES.has(eventsHash)) {
      continue;
    }

    totalConfirmedBatches++;
    if (!hashToBatches.has(eventsHash)) {
      hashToBatches.set(eventsHash, []);
    }
    hashToBatches.get(eventsHash)!.push({ signature: sigInfo.signature, batchId });
  }

  // 3. Detect duplicate events hashes
  const duplicateHashes: DuplicateEventsHashReport["duplicateHashes"] = [];
  for (const [eventsHash, batchList] of hashToBatches.entries()) {
    if (batchList.length > 1) {
      duplicateHashes.push({
        eventsHash,
        count: batchList.length,
        signatures: batchList.map((b) => b.signature),
        batchIds: batchList.map((b) => b.batchId),
      });
    }
  }

  const report: DuplicateEventsHashReport = {
    totalSignaturesScanned: allSignatures.length,
    totalConfirmedBatches,
    uniqueEventsHashes: hashToBatches.size,
    duplicateHashes,
    ok: duplicateHashes.length === 0,
  };

  if (failOnError && !report.ok) {
    const errorDetails = duplicateHashes
      .map(
        (d) =>
          `Hash ${d.eventsHash} appears in ${d.count} confirmed batches (batch IDs: ${d.batchIds.join(", ")}; signatures: ${d.signatures.join(", ")})`
      )
      .join("; ");
    throw new Error(`On-chain duplicate events hash detected! ${errorDetails}`);
  }

  return report;
}
